import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('State & useState', () => {
  test('Displays initial count of 0', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#count');
if (!el) throw new Error('No element with id "count" found');
if (!el.textContent.includes('0')) throw new Error('Initial count should be 0');
  });

  test('Increment button increases count by 1', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#increment');
if (!btn) throw new Error('No button with id "increment" found');
const before = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [0])[0]);
btn.click();
await tick();
const after = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [0])[0]);
if (after !== before + 1) throw new Error('Count should increase by 1 after clicking Increment (was ' + before + ', now ' + after + ')');
  });

  test('Decrement button decreases count by 1', async () => {
    const { container: root } = render(<App />);
    const btn = root.querySelector('#decrement');
if (!btn) throw new Error('No button with id "decrement" found');
const before = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [0])[0]);
btn.click();
await tick();
const after = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [0])[0]);
if (after !== before - 1) throw new Error('Count should decrease by 1 after clicking Decrement (was ' + before + ', now ' + after + ')');
  });

  test('Reset button sets count to 0', async () => {
    const { container: root } = render(<App />);
    const reset = root.querySelector('#reset');
if (!reset) throw new Error('No button with id "reset" found');
const inc = root.querySelector('#increment');
if (inc) { inc.click(); await tick(); inc.click(); await tick(); }
reset.click();
await tick();
const after = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [NaN])[0]);
if (after !== 0) throw new Error('Count should be 0 after clicking Reset (was ' + after + ')');
  });
});
